'use client';

import { motion } from 'framer-motion';
import { Calendar, Weight, Ruler, User, Check, X } from 'lucide-react';

interface Item {
  id: string;
  yourName: string;
  davidDateOfBirth: string;
  davidWeight: string;
  davidLength: string;
  hasUnibrow: boolean;
  createdAt: string;
}

interface ItemListProps {
  items: Item[];
}

export function ItemList({ items }: ItemListProps) {
  if (items.length === 0) {
    return (
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="text-center py-16"
      >
        <div className="inline-block p-8 bg-gradient-to-br from-blue-50 to-indigo-50 rounded-2xl shadow-lg">
          <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-4">
            <Calendar className="w-8 h-8 text-blue-600" />
          </div>
          <p className="text-gray-700 text-xl font-bold mb-2">
            No entries yet
          </p>
          <p className="text-gray-500">
            Start tracking David's growth by adding your first entry!
          </p>
        </div>
      </motion.div>
    );
  }

  const calculateAge = (birthDate: string) => {
    const today = new Date();
    const birth = new Date(birthDate);
    const ageInMs = today.getTime() - birth.getTime();
    const ageInDays = Math.floor(ageInMs / (1000 * 60 * 60 * 24));

    if (ageInDays < 31) {
      return `${ageInDays} days old`;
    } else if (ageInDays < 365) {
      const months = Math.floor(ageInDays / 30);
      return `${months} month${months > 1 ? 's' : ''} old`;
    } else {
      const years = Math.floor(ageInDays / 365);
      return `${years} year${years > 1 ? 's' : ''} old`;
    }
  };

  return (
    <div className="
      grid
      grid-cols-1
      lg:grid-cols-2
      gap-6
    ">
      {items.map((item, index) => (
        <motion.div
          key={item.id}
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: index * 0.1 }}
          whileHover={{ y: -5 }}
          className="
            bg-white
            rounded-2xl
            shadow-lg hover:shadow-2xl
            border-2 border-gray-100
            overflow-hidden
            transition-shadow duration-300
          "
        >
          {/* Header Section */}
          <div className="bg-gradient-to-r from-blue-500 to-indigo-600 p-6 text-white">
            <div className="flex items-center justify-between mb-2">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center">
                  <User className="w-6 h-6" />
                </div>
                <h3 className="text-2xl font-bold">
                  {item.yourName}
                </h3>
              </div>
              <span className="text-xs bg-white/30 backdrop-blur-sm px-3 py-1.5 rounded-full font-medium">
                {new Date(item.createdAt).toLocaleDateString()}
              </span>
            </div>
          </div>

          {/* David's Info Section */}
          <div className="p-6 bg-gradient-to-br from-purple-50 to-pink-50">
            <div className="flex items-center gap-2 mb-4">
              <div className="h-1 flex-1 bg-gradient-to-r from-purple-400 to-pink-400 rounded"></div>
              <h4 className="text-lg font-bold text-purple-900">Oklade</h4>
              <div className="h-1 flex-1 bg-gradient-to-r from-pink-400 to-purple-400 rounded"></div>
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
              {/* Date of Birth */}
              <motion.div
                whileHover={{ scale: 1.05 }}
                className="bg-white p-4 rounded-xl border-2 border-purple-200 shadow-sm hover:shadow-md transition-shadow"
              >
                <div className="flex items-center gap-2 text-purple-600 mb-2">
                  <Calendar className="w-4 h-4" />
                  <span className="text-xs font-bold uppercase tracking-wide">Datum rodjenja</span>
                </div>
                <div className="text-sm font-bold text-gray-800">
                  {new Date(item.davidDateOfBirth).toLocaleDateString('en-US', {
                    month: 'short',
                    day: 'numeric',
                    year: 'numeric'
                  })}
                </div>
                <div className="text-xs text-purple-600 mt-1 font-medium">
                  {calculateAge(item.davidDateOfBirth)}
                </div>
              </motion.div>

              {/* Weight */}
              <motion.div
                whileHover={{ scale: 1.05 }}
                className="bg-white p-4 rounded-xl border-2 border-purple-200 shadow-sm hover:shadow-md transition-shadow"
              >
                <div className="flex items-center gap-2 text-purple-600 mb-2">
                  <Weight className="w-4 h-4" />
                  <span className="text-xs font-bold uppercase tracking-wide">Tezina</span>
                </div>
                <div className="text-lg font-bold text-gray-800">
                  {item.davidWeight} <span className="text-sm text-gray-500 font-normal">kg</span>
                </div>
              </motion.div>

              {/* Length */}
              <motion.div
                whileHover={{ scale: 1.05 }}
                className="bg-white p-4 rounded-xl border-2 border-purple-200 shadow-sm hover:shadow-md transition-shadow"
              >
                <div className="flex items-center gap-2 text-purple-600 mb-2">
                  <Ruler className="w-4 h-4" />
                  <span className="text-xs font-bold uppercase tracking-wide">Duzina</span>
                </div>
                <div className="text-lg font-bold text-gray-800">
                  {item.davidLength} <span className="text-sm text-gray-500 font-normal">cm</span>
                </div>
              </motion.div>

              {/* Unibrow */}
              <motion.div
                whileHover={{ scale: 1.05 }}
                className="bg-white p-4 rounded-xl border-2 border-purple-200 shadow-sm hover:shadow-md transition-shadow"
              >
                <div className="flex items-center gap-2 text-purple-600 mb-2">
                  {item.hasUnibrow ? <Check className="w-4 h-4" /> : <X className="w-4 h-4" />}
                  <span className="text-xs font-bold uppercase tracking-wide">Spojena obrva</span>
                </div>
                <div className={`text-lg font-bold ${item.hasUnibrow ? 'text-green-600' : 'text-red-600'}`}>
                  {item.hasUnibrow ? 'Da' : 'Ne'}
                </div>
              </motion.div>
            </div>
          </div>
        </motion.div>
      ))}
    </div>
  );
}
